{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Clear Export Status\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Resets selected media items' custom color, restoring them to their parent track's color. Use this after exporting items to clear the "needs export" visual flag.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Usage\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Select one or more media items that have been exported\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Run this script\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Item colors are reset to match their track\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Notes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Companion script to "Mark Item Needs Export"\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Sets item color to 0 (inherit from track)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Removes all takes from selected items, converting them to empty items. Preserves item position, length, track, and color.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Special thanks to Rodrigo Robinet for the request.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Markers to Take Markers\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Copies project markers that fall within selected media items' time ranges and applies them as take markers on each item's active take, preserving marker names and colors.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Usage\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Place project markers on the timeline with descriptive names\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Select one or more media items\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Run this script\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab A dialog will ask whether to remove the original project markers\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Notes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Only markers within each item's time range are copied\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Accounts for take start offset and playrate per item\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Works with multiple selected items at once\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Requires REAPER v5.20+ (SetTakeMarker API)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Batch Rename and Enumerate\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Micro-renamer for quickly applying a base name with sequential numbering to selected media items. Ideal for enumerating sound variations.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Usage\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Select one or more media items\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Run this script\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab The base name is auto-detected from the first selected item\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab Adjust base name, separator, start number, and padding as needed\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 5.\tx360\tab Review the live preview, then click Apply\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Requirements\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab ReaImGui\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Find and Replace Take Names\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Batch find-and-replace text in the take names of selected media items.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Usage\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Select one or more media items\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Run this script\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Enter the text to find and the replacement text\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab Click Replace to apply\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 5.\tx360\tab Select new items and repeat as needed\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Requirements\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab ReaImGui\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Subproject Render and Color\par}
{\pard \ql \f0 \sa180 \li0 \fi0 Saves and renders the current subproject, then navigates to the parent project to color the rendered subproject item with the "needs export" color, and returns to the subproject.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Usage\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab Work in a subproject\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Run this script (replaces your usual save/render hotkey)\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab The subproject is saved and rendered\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 4.\tx360\tab The rendered item in the parent project is colored\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 5.\tx360\tab You're returned to the subproject\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Notes\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Requires SWS Extension\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Shares the "needs export" color with Kokkinos_MarkItemNeedsExport\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Automatically mutes video track sends before render\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab Matches the parent item by .rpp source filename (safe with renamed takes)\sa180\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 Dockable focus timer with task-based session logging. Set a target duration, watch the color shift as you progress (green -> yellow -> orange -> red overtime), and log time against Project / Category / Task records that accumulate across sessions. Requires: ReaImGui\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel0 \b \fs36 Kokkinos-Scripts\par}
{\pard \ql \f0 \sa180 \li0 \fi0 A collection of ReaScripts for REAPER by Cookie (Chris Kokkinos).\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Scripts\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\b External Window Docker} \u8212- Embed external application windows (browsers, media players, etc.) directly into REAPER's docker system.\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 \bullet \tx360\tab {\b Markers to Take Markers} \u8212- Copy project markers to take markers on selected media items, preserving names and colors.\sa180\par}
{\pard \ql \f0 \sa180 \li0 \fi0 \outlinelevel1 \b \fs32 Installation\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 1.\tx360\tab In REAPER, go to Extensions > ReaPack > Import repositories\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 2.\tx360\tab Paste: {\f1 https://github.com/chriskodekkinos/Kokkinos-Scripts/raw/master/index.xml}\par}
{\pard \ql \f0 \sa0 \li360 \fi-360 3.\tx360\tab Browse and install scripts via Extensions > ReaPack > Browse packages\sa180\par}
}
